  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "To date, the role of TIPS in the preoperative setting of patients requiring elective and emergency surgery remains unclear. Moreover, little quantitative evidence is available to know the number of patients who can undergo surgery after preoperative TIPS and their associated postoperative outcomes; for example, postoperative liver-related events (LRE).",
      "reason": "The current state of knowledge and some uncertainties are described (role remains unclear; little quantitative evidence), but the evidence does not clearly cover all important uncertainties in detail."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "In this systematic review and meta-analysis, we examined the evidence on transjugular intrahepatic portosystemic shunt (TIPS) as a bridge to elective and emergency surgery in cirrhotic patients. We aimed to assess the perioperative characteristics, management approaches, and outcomes of this intervention, which is used to achieve portal decompression and enable the safe performance of elective and emergent surgery.",
      "reason": "The need to conduct the review is somewhat implied by the stated purpose/aims and the clinical relevance of enabling safe surgery, but the importance/need is not explicitly justified in the retrieved text beyond these aims."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes existing similar systematic reviews or explains the need for the current review in relation to prior reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This intervention, which is used to achieve portal decompression and enable the safe performance of elective and emergent surgery.",
      "reason": "A brief proposed mechanism/context for how TIPS is expected to work is described (portal decompression enabling safer elective/emergent surgery)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence presents a logic model or other hypothesised relationships between intervention components and outcomes for this complex/delivery context."
    }
  ],
  "confidence": 46
}

